def extract_number_and_supplement_from_issue_element(issue):
    number = None
    supplement = None
    match = re.search(r'<issue>(.*)</issue>', issue)
    if match:
        issue_text = match.group(1)
        number_match = re.search(r'(\d+)', issue_text)
        if number_match:
            number = int(number_match.group(1))
        supplement_match = re.search(r'suppl|supplement', issue_text, re.IGNORECASE)
        if supplement_match:
            supplement = 'supplement'
    return number, supplement

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    if debug:
        print("Pretty printing with indent level", indent)
    result = ""
    if self.is_leaf():
        result += " " * indent + str(self.value) + "\n"
    else:
        result += " " * indent + "(" + str(self.value) + "\n"
        for child in self.children:
            result += child.pretty(indent + 2, debug)
        result += " " * indent + ")" + "\n"
    return result

