def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if document.startswith('<?xml'):
        # Parse XRD format
        root = ET.fromstring(document)
        ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
        xrd = root.find('xrd:XRD', ns)
        subject = xrd.find('xrd:Subject', ns).text
        links = xrd.findall('xrd:Link', ns)
        return {
            'subject': subject,
            'links': [
                {
                    'rel': link.attrib['rel'],
                    'href': link.attrib['href'],
                    'type': link.attrib['type']
                }
                for link in links
            ]
        }
    else:
        # Parse JSON format
        data = json.loads(document)
        return {
            'subject': data['subject'],
            'links': [
                {
                    'rel': link['rel'],
                    'href': link['href'],
                    'type': link['type']
                }
                for link in data['links']
            ]
        }

