def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("Spec content is missing")

    spec_data = yaml.safe_load(spec_content)

    if "name" not in spec_data:
        raise IRValidatorException("Name is missing in spec file")

    if "version" not in spec_data:
        raise IRValidatorException("Version is missing in spec file")

    if "description" not in spec_data:
        raise IRValidatorException("Description is missing in spec file")

    if "inputs" not in spec_data:
        raise IRValidatorException("Inputs are missing in spec file")

    if "outputs" not in spec_data:
        raise IRValidatorException("Outputs are missing in spec file")

    if "parameters" not in spec_data:
        raise IRValidatorException("Parameters are missing in spec file")

    return spec_data

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise ValueError("YAML file path is required")

    with open(yaml_file, "r") as f:
        data = yaml.safe_load(f)

    if not data:
        raise IRValidatorException("YAML file is empty")

    if "name" not in data:
        raise IRValidatorException("'name' field is missing in YAML file")

    if "version" not in data:
        raise IRValidatorException("'version' field is missing in YAML file")

    if "description" not in data:
        raise IRValidatorException("'description' field is missing in YAML file")

    if "inputs" not in data:
        raise IRValidatorException("'inputs' field is missing in YAML file")

    if "outputs" not in data:
        raise IRValidatorException("'outputs' field is missing in YAML file")

    if "parameters" not in data:
        raise IRValidatorException("'parameters' field is missing in YAML file")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    for group_name, group_dict in parser_dict.items():
        if group_name == "include":
            for include_name, include_dict in group_dict.items():
                if include_name == "dict":
                    for include_key, include_value in include_dict.items():
                        if include_key == "name":
                            include_name = include_value
                        elif include_key == "path":
                            include_path = include_value
                        elif include_key == "type":
                            include_type = include_value
                        else:
                            raise ValueError(f"Invalid include key: {include_key}")
                    if include_type == "dict":
                        include_dict = self._include_groups(include_dict)
                    elif include_type == "list":
                        include_list = self._include_groups(include_dict)
                    else:
                        raise ValueError(f"Invalid include type: {include_type}")
                    parser_dict[include_name] = include_dict
                    del parser_dict[group_name]
                    break
    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    # Resolve arguments' values from spec
    for arg in self.spec.args:
        if arg.default is not None:
            arg.value = arg.default

    # Resolve arguments' values from other sources
    for arg in self.spec.args:
        if arg.value is None and arg.source is not None:
            arg.value = arg.source.get_value()

    # Set default values for missing arguments
    for arg in self.spec.args:
        if arg.value is None:
            arg.value = arg.default

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    deprecated_args = {}
    for arg in self.args:
        if arg.deprecated:
            deprecated_args[arg.name] = arg.deprecated
    return deprecated_args

def validate_arg_deprecation(self, cli_args, answer_file_args):
    deprecated_args = []
    for arg in cli_args:
        if arg in answer_file_args:
            deprecated_args.append(arg)
    if deprecated_args:
        print("The following arguments are deprecated:")
        for arg in deprecated_args:
            print(f"- {arg}")

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    options = []
    for option in self.options:
        if option.command == command_name:
            options.append(option)
    return options

def get_silent_args(self, args):
    silenced_args = []
    for arg in args:
        if arg.startswith("-"):
            silenced_args.append(arg)
    return silenced_args

def validate_requires_args(self, args):
    for arg in self.required_args:
        if arg not in args:
            raise ValueError(f"Missing required argument: {arg}")

def _get_conditionally_required_args(command_name, options_spec, args):
    required_args = []
    for option in options_spec:
        if option["required_when"]:
            for condition in option["required_when"]:
                if condition["command"] == command_name and condition["args"] in args:
                    required_args.append(option["name"])
    return required_args

def validate_length_args(self, args):
    for arg in args:
        if len(arg) > self.length:
            raise ValueError(f"Argument {arg} is longer than the specified length of {self.length}")

def validate_choices_args(args):
    for arg in args:
        if arg not in self.available_choices:
            raise ValueError(f"Invalid choice: {arg}")

def validate_min_max_args(self, args):
    if len(args) < self.min_args or len(args) > self.max_args:
        raise ValueError("Invalid number of arguments")

def get_nested_custom_and_control_args(self, args):
    control_args = {}
    nested_args = {}
    for arg in args:
        if arg.startswith("control_"):
            control_args[arg] = args[arg]
        elif arg.startswith("nested_"):
            nested_args[arg] = args[arg]
        elif arg.startswith("custom_"):
            nested_args[arg] = args[arg]
        else:
            raise ValueError(f"Invalid argument: {arg}")
    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    if extra_vars is not None:
        vars_dict.update(extra_vars)
    return vars_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    plugin_spec = get_plugin_spec(plugin_dir)
    flatten_dict = {}
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            for sub_key, sub_value in value.items():
                flatten_dict[f"{key}.{sub_key}"] = sub_value
        else:
            flatten_dict[key] = value
    return flatten_dict

def inject_config(self):
    if not os.environ.get("CONFIG_PATH"):
        os.environ["CONFIG_PATH"] = "config.json"

def strip_root(path, root):
    if not path.startswith(root):
        raise ValueError("Path does not start with root")
    return path[len(root):]
